enum Size {
  Small,
  Medium,
  Large,
}

enum Milk {
  None,
  Regular,
  Oat,
  Almond,
}

type Coffee = {
  size: Size;
  milk: Milk;
  shots: Int;
}

fn Coffee.price(self) -> Float64 {
  var total = 3.00;
  if size == Size.Medium { total = total + 1.00; }
  if size == Size.Large { total = total + 2.00; }
  if milk != Milk.None { total = total + 0.50; }
  if milk == Milk.Oat || milk == Milk.Almond { total = total + 0.25; }
  if shots > 2 {
    total = total + ((shots - 2) as Float64) * 0.75;
  }
  return total;
}

fn main() -> Int {
  let latte = Coffee{ size: Size.Large; milk: Milk.Oat; shots: 3; };
  return (latte.price() * 100.0) as Int;
}
